<script lang="ts">
 import {planBlend} from '@vinea/domain';
 let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let project=$state('');
 $effect(()=>{if(!project)project=model.projects.find(p=>model.recipes.some(r=>r.project_id===p.id&&model.trials.some(trial=>trial.recipe_id===r.id)))?.id??model.projects[0]?.id??'';});
 let recipes=$derived(model.recipes.filter(r=>r.project_id===project));
 function estimate(recipe:Record<string,any>){try{const snapshot=recipe.snapshot?.positions??[];return planBlend(recipe.components.map((c:any)=>{const p=model.positions.find(p=>p.id===c.position_id),lot=model.lots.find(l=>l.id===p?.lot_id),frozen=Array.isArray(snapshot)?snapshot.find((p:any)=>p.id===c.position_id):null;const superseded=new Set(model.analyses.map(a=>a.supersedes).filter(Boolean));const measurements=frozen?.analyses??model.analyses;const replaced=new Set(measurements.map((a:any)=>a.supersedes).filter(Boolean));const a=[...measurements].sort((a:any,b:any)=>Date.parse(b.measured_at)-Date.parse(a.measured_at)).find((a:any)=>(frozen||a.lot_id===lot?.id)&&a.parameter==='alcohol'&&a.quality==='measured'&&!replaced.has(a.id));return {id:c.position_id,volume:c.quantity_l,available:c.quantity_l,cost:frozen?.cost_per_l??lot?.cost_per_l??'0',alcohol:a?.value??null,unit:a?.unit??null,method:a?.method??null,blocked:false};}));}catch{return null;}}
</script>
<section class="card"><div class="comparison-heading"><h2>{t('compareVariants')}</h2><label><span class="sr-only">{t('project_id')}</span><select bind:value={project}>{#each model.projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label></div><p class="muted">{t('comparisonHint')}</p>{#each model.briefs.filter(b=>b.project_id===project&&b.reference_lot_id) as brief}{@const reference=model.lots.find(l=>l.id===brief.reference_lot_id)}<details class="reference"><summary>{t('reference_lot_id')}: {reference?.name??'—'}</summary><p>{brief.style}</p>{#if reference}<p>{reference.code} · {reference.vintage}</p>{#each ['alcohol','sugar','acidity','ph','free_so2'] as parameter}{@const a=model.analyses.find(a=>a.lot_id===reference.id&&a.parameter===parameter&&a.quality==='measured'&&!model.analyses.some(n=>n.supersedes===a.id))}<span>{parameter==='ph'?'pH':t(parameter)} · {a?.value??'—'} {a?.unit??''} · {a?.method??''}</span>{/each}{/if}</details>{/each}<div class="variants">{#each recipes as recipe}{@const result=estimate(recipe)}{@const trials=model.trials.filter(trial=>trial.recipe_id===recipe.id)}{@const ratings=model.evaluations.filter(e=>trials.some(trial=>trial.id===e.trial_id))}<article><div class="variant-meta"><span class={'pill '+(recipe.state==='draft'?'info':'good')}>{t(recipe.state)}</span><span>v{recipe.revision}</span></div><h3>{recipe.name}</h3><div class="recipe-stats"><strong>{recipe.target_l} <small>L</small></strong>{#if result}<span>{result.costPerLiter} €/L</span>{/if}</div><div class="recipe-share" aria-hidden="true">{#each recipe.components as c,i}<span style:flex={Number(c.quantity_l)} style:background={['#258463','#6fa4a8','#b28f58','#82975f'][i%4]}></span>{/each}</div><ul>{#each recipe.components as c}<li><span>{model.positions.find(p=>p.id===c.position_id)?.lot_code??t('uxUnknown')}</span><strong>{c.quantity_l} L</strong></li>{/each}</ul>{#if result}<p class="muted">{t('alcohol')} ≈ {result.alcohol??t('uxMissing')}{result.alcohol?' % vol':''}</p>{/if}<div class="score"><span>{t('uxScores')}</span><strong>{ratings.length?(ratings.reduce((n,e)=>n+Number(e.score),0)/ratings.length).toFixed(1)+' / 100':t('uxNoRatings')}</strong>{#if ratings.length}<small>{ratings.length} · {trials.map(t=>t.blind_code).join(' / ')}</small>{/if}</div></article>{:else}<p class="empty-state">{t('uxEmptyHint')}</p>{/each}</div><p class="ph-hint">{t('ph')}</p></section>
<style>.comparison-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:15px}.comparison-heading h2{margin:0}.comparison-heading select{max-width:340px;font-size:12px}.reference{margin:15px 0 22px;padding:10px 16px;background:#f4f8f5;border:1px solid var(--line);border-radius:9px}.reference summary{font-size:12px}.reference>span{display:block;font-size:12px;color:var(--muted);margin:7px 0}.variants{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}article{border:1px solid var(--line);border-radius:12px;padding:20px;min-width:0}.variant-meta{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:var(--muted)}h3{font-size:14px;min-height:43px;margin:16px 0}.recipe-stats{display:flex;justify-content:space-between;align-items:end;gap:10px}.recipe-stats strong{font-size:23px}.recipe-stats small{font-size:11px;color:var(--muted);font-weight:400}.recipe-stats>span{font-size:12px;color:var(--muted)}.recipe-share{display:flex;height:9px;gap:2px;border-radius:4px;overflow:hidden;margin:17px 0}ul{list-style:none;padding:0;display:grid;gap:10px;font-size:11px}li{display:flex;justify-content:space-between;gap:10px}li strong{font-size:11px}.score{padding-top:15px;margin-top:16px;border-top:1px solid var(--line);display:grid;gap:6px}.score>span,.score small{font-size:10px;color:var(--muted)}.score strong{font-size:18px;color:var(--brand)}.ph-hint{font-size:11px;color:var(--muted);margin:18px 0 0}@media(max-width:640px){.comparison-heading{flex-direction:column;align-items:flex-start}.comparison-heading label,.comparison-heading select{width:100%;max-width:100%}.variants{grid-template-columns:1fr}h3{min-height:0}}
</style>
